#include <iomanip>
#include <sstream>
#include <string>
#include <string_view>

std::string row(std::string_view name, double price)
{
    std::ostringstream out{};
    out << std::left << std::setw(12) << name
        << std::right << std::setw(8) << std::fixed << std::setprecision(2) << price;
    return out.str();
}
